CREATE OR REPLACE FUNCTION public.valid_unified_chat_context(_room uuid,_order uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user IS NOT NULL AND EXISTS(SELECT 1 FROM public.chat_rooms r WHERE r.id=_room AND r.merged_into_room_id IS NULL AND (r.participant_a IS NOT NULL OR r.is_operation) AND public.can_access_unified_chat(r.id,_user) AND (_order IS NULL OR EXISTS(SELECT 1 FROM public.orders o WHERE o.id=_order AND public.can_access_order_chat(o.id,_user) AND (r.is_operation OR (public.is_staff(r.participant_a) AND public.is_staff(r.participant_b)) OR o.driver_id IN(r.participant_a,r.participant_b))))); $$;
CREATE POLICY unified_message_context_boundary ON public.messages AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.valid_unified_chat_context(room_id,order_id,auth.uid()));
REVOKE UPDATE ON public.messages FROM authenticated;
REVOKE ALL ON FUNCTION public.valid_unified_chat_context(uuid,uuid,uuid),public.get_or_create_driver_room(uuid),public.get_or_create_staff_room(uuid),public.get_chat_room_team_members(uuid[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.valid_unified_chat_context(uuid,uuid,uuid),public.get_or_create_driver_room(uuid),public.get_or_create_staff_room(uuid),public.get_chat_room_team_members(uuid[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.can_access_direct_room(_room_id uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_access_unified_chat(_room_id,_user) $$;
CREATE OR REPLACE FUNCTION public.can_access_staff_room(_room_id uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_access_unified_chat(_room_id,_user) $$;
